namespace scratchbird::engine::internal_api { namespace { std::mutex m; using D=scratchbird::engine::sblr::SblrDdlAlterExtensionDescriptorV1; std::map<std::string,D> live,used; std::string key(const D&d){return {(const char*)d.body.data(),d.body.size()};} bool tag(const EngineRequestContext&c,const char*x){return c.security_context_present&&std::find(c.trace_tags.begin(),c.trace_tags.end(),x)!=c.trace_tags.end();} EngineApiDiagnostic diag(std::string c,std::string d){return MakeEngineApiDiagnostic(std::move(c),std::move(d),{});} }
SblrDdlAlterExtensionCoordinationResult CompileSblrDdlAlterExtensionDescriptor(const EngineRequestContext&c,const std::string& n,std::uint64_t generation){std::lock_guard l(m);SblrDdlAlterExtensionCoordinationResult o;if(!tag(c,"private_ddl_alter_extension_binder")||!c.statement_metadata_snapshot_engine_owned||n!=c.statement_uuid.canonical||generation==0||!tag(c,"cluster_provider_admitted")||!tag(c,"cluster_route_fence_admitted")){o.diagnostic=diag("CLUSTER.GATEWAY_CLUSTER_FALLTHROUGH_FORBIDDEN","sblr.ddl_alter_extension.cluster_gate");return o;}o.descriptor.body[0]=1;o.descriptor.body[16]=1;for(int i=0;i<8;++i)o.descriptor.body[80+i]=std::uint8_t(generation>>(8*i));if(scratchbird::engine::sblr::EncodeSblrDdlAlterExtensionDescriptorV1(o.descriptor).empty()){o.diagnostic=diag("SBLR.OPERAND.INVALID","sblr.ddl_alter_extension.descriptor_invalid");return o;}live[key(o.descriptor)]=o.descriptor;o.ok=true;o.diagnostic=diag("OK","ok");return o;}
SblrDdlAlterExtensionCoordinationResult ConsumeSblrDdlAlterExtensionDescriptor(const EngineRequestContext&c,const D&d){std::lock_guard l(m);SblrDdlAlterExtensionCoordinationResult o;auto k=key(d);if(!tag(c,"private_ddl_alter_extension")){o.diagnostic=diag("SECURITY.ACCESS_DENIED","sblr.ddl_alter_extension.hidden");return o;}auto i=live.find(k);if(i==live.end()){o.diagnostic=used.count(k)?diag("MGA.TRANSACTION.STALE","sblr.ddl_alter_extension.stale"):diag("SECURITY.ACCESS_DENIED","sblr.ddl_alter_extension.hidden");return o;}if(c.query_cancellation_requested&&c.query_cancellation_requested()){o.diagnostic=diag("PROCESS.CANCELLED","sblr.ddl_alter_extension.cancelled");return o;}used[k]=d;live.erase(i);o.ok=true;o.descriptor=d;o.diagnostic=diag("OK","ok");return o;}}
